/* Four independent MOD slots. Fixed storage; existing lock and MIDI queue. */
static const char *mod_fields[MOD_FIELDS]={"on","wave","sync","rate","hz","depth","offset","phase","dest","threshold","c0","c1","c2","c3","c4","c5","c6","c7"};
static const int mod_lo[MOD_FIELDS]={0,0,0,0,0,-100,-100,0,0,-100,-100,-100,-100,-100,-100,-100,-100,-100};
static const int mod_hi[MOD_FIELDS]={1,7,1,6,1000,100,100,359,7,100,100,100,100,100,100,100,100,100};
static const double mod_periods[]={.25,.5,1,2,4,8,16};
static void mod_defaults(ModLane *m){memset(m,0,sizeof *m);for(int j=0;j<2;j++){m->osc[j].f[2]=1;m->osc[j].f[3]=2;m->osc[j].f[4]=500;m->osc[j].f[5]=50;for(int k=0;k<8;k++)m->osc[j].f[10+k]=(int)lround(100*sin(k*6.283185307179586/8));}}
static double mod_frequency(const ModOsc *o,double bpm){return o->f[2]?bpm/(60*mod_periods[o->f[3]]):.05*pow(400.,o->f[4]/1000.);}
static void mod_coefficients(Engine *e,int s){double x=e->mod[s].mix/100.;e->mod_weight[s][0]=.5*(1-x);e->mod_weight[s][1]=.5*(1+x);for(int j=0;j<2;j++){ModOsc *o=&e->mod[s].osc[j];e->mod_hz[s][j]=mod_frequency(o,e->mod_bpm);e->mod_depth[s][j]=o->f[5]/100.;e->mod_offset[s][j]=o->f[6]/100.;}}
static void mod_init(Engine *e){e->mod_selected=0;e->mod_bpm=120;e->mod_seconds=e->mod_beats=0;for(int s=0;s<MOD_SLOTS;s++){mod_defaults(&e->mod[s]);e->mod_pad[s]=-1;mod_coefficients(e,s);}for(int i=0;i<LANES;i++)e->mod_owner[i]=-1;memset(e->mod_armed,0,sizeof e->mod_armed);memset(e->mod_phase,0,sizeof e->mod_phase);memset(e->mod_latch_valid,0,sizeof e->mod_latch_valid);memset(e->mod_running_cache,0,sizeof e->mod_running_cache);e->mod_trace_dirty=(1u<<MOD_SLOTS)-1;}
static int mod_slot_for(const Engine *e,int lane){for(int s=0;s<MOD_SLOTS;s++)if(e->mod_pad[s]==lane)return s;return -1;}
static void mod_notify_selected(Engine *e){for(int k=0;k<MOD_PER_LANE;k++)notify_id(e,MOD_ID+LANES*MOD_PER_LANE+k);/* Keep global visual history: the next snapshot compares the new slot. */}
/* Legacy lane-prefixed keys are accepted only for an already assigned lane. */
static void mod_key(int id,char *key,int size){int lane=id/MOD_PER_LANE,k=id%MOD_PER_LANE;char tail[40];if(!k)snprintf(tail,sizeof tail,"mod_mix");else{k--;snprintf(tail,sizeof tail,"mod%d_%s",k/MOD_FIELDS,mod_fields[k%MOD_FIELDS]);}if(lane<LANES)snprintf(key,size,"l%d_%s",lane,tail);else snprintf(key,size,"%s",tail);}
static int mod_parse(Engine *e,const char *key,int *slot,int *k){const char *s=key;*slot=e->mod_selected;int li;const char *tail;if(lane_prefix(key,&li,&tail)){*slot=mod_slot_for(e,li);s=tail;}if(!strcmp(s,"mod_mix")){*k=0;return 1;}if(strncmp(s,"mod",3)||s[3]<'0'||s[3]>'1'||s[4]!='_')return 0;for(int f=0;f<MOD_FIELDS;f++)if(!strcmp(s+5,mod_fields[f])){*k=1+(s[3]-'0')*MOD_FIELDS+f;return 1;}return 0;}
static int mod_set(Engine *e,const char *key,int value){int s,k;
 if(parse_suffix(key,"mod_choose",MOD_SLOTS,&s)){if(value>0&&e->mod_selected!=s){e->mod_selected=s;mod_notify_selected(e);e->revision++;}return 1;}
 if(!strcmp(key,"mod_pad")){s=e->mod_selected;int pad=clampi(value,0,LANES)-1;if(pad==e->mod_pad[s])return 1;/* one slot per lane; occupied choices are rejected */for(int other=0;other<MOD_SLOTS;other++)if(other!=s&&pad>=0&&e->mod_pad[other]==pad){mod_notify_selected(e);return 1;}int previous=e->mod_pad[s];if(previous>=0){if(e->mod_owner[previous]>=0)e->release_pending|=1u<<previous;memset(e->mod_armed[previous],0,sizeof e->mod_armed[previous]);e->mod_latch_valid[previous]=0;}if(pad>=0){memset(e->mod_armed[pad],0,sizeof e->mod_armed[pad]);e->mod_latch_valid[pad]=0;}e->mod_pad[s]=pad;memset(e->mod_running_cache[s],0,sizeof e->mod_running_cache[s]);mod_notify_selected(e);e->revision++;return 1;}
 if(!strcmp(key,"mod_slot"))return 1;
 if(!mod_parse(e,key,&s,&k))return 0;if(s<0)return 1;int *p,lo=-100,hi=100;if(!k)p=&e->mod[s].mix;else{int f=(k-1)%MOD_FIELDS;p=&e->mod[s].osc[(k-1)/MOD_FIELDS].f[f];lo=mod_lo[f];hi=mod_hi[f];}value=clampi(value,lo,hi);if(*p==value)return 1;*p=value;
 int f=k?(k-1)%MOD_FIELDS:-1,j=k?(k-1)/MOD_FIELDS:0,i=e->mod_pad[s];int common=!k||f==0||f==1||f==7||f>=10,local=f==5||f==6||f==8||f==9;
 if(i>=0){if(common){if(e->mod_owner[i]>=0)e->release_pending|=1u<<i;memset(e->mod_armed[i],0,sizeof e->mod_armed[i]);}else if(local){if(e->mod_owner[i]==j)e->release_pending|=1u<<i;e->mod_armed[i][j]=0;}}
 if(f==1||f==2||f==3||f==4||f==5||f==6||f==7||f>=10)e->mod_trace_dirty|=1u<<s;
 if(!k||f==2||f==3||f==4||f==5||f==6)mod_coefficients(e,s);
 if(i>=0)notify_id(e,MOD_ID+i*MOD_PER_LANE+k);if(s==e->mod_selected)notify_id(e,MOD_ID+LANES*MOD_PER_LANE+k);e->revision++;return 1;}
static int mod_running(Engine *e,int s,int j){int i=e->mod_pad[s];return i>=0&&e->mod[s].osc[j].f[0]&&audible(e,i);}
/* Same bounded wave functions for playback and edit-only preview. Random values
   are computed only by random shapes; the preview uses a fixed seed. */
static double mod_shape(const ModOsc *o,double phase,unsigned seed){double cycle=floor(phase),p=phase-cycle;
 switch(o->f[1]){case 0:return sin(6.283185307179586*p);case 1:return 1-4*fabs(p-.5);case 2:return 2*p-1;case 3:return 1-2*p;case 4:return p<.5?1:-1;case 5:return (mix32(seed^(unsigned)(int64_t)cycle)/4294967295.)*2-1;case 6:{double a=(mix32(seed^(unsigned)(int64_t)cycle)/4294967295.)*2-1,b=(mix32(seed^(unsigned)((int64_t)cycle+1))/4294967295.)*2-1;return a+(b-a)*p*p*(3-2*p);}default:{double z=p*8;int k=(int)z;return (o->f[10+k%8]+(o->f[10+(k+1)%8]-o->f[10+k%8])*(z-k))/100.;}}
}
static double mod_wave_slot(const Engine *e,int s,int j,double dt){const ModOsc *o=&e->mod[s].osc[j];int i=e->mod_pad[s];unsigned seed=(i>=0?e->lane[i].seed:0x1933u)^(unsigned)(j*0x29a583u);return mod_shape(o,e->mod_phase[s][j]+dt*e->mod_hz[s][j]+o->f[7]/360.,seed);}
static double mod_mixed_slot(Engine *e,int s,double dt){double v=0;for(int j=0;j<2;j++)if(e->mod_weight[s][j]!=0&&mod_running(e,s,j))v+=e->mod_weight[s][j]*mod_wave_slot(e,s,j,dt);return v;}
static double mod_amount_mixed(const Engine *e,int s,int dest,double mixed){double v=0;for(int j=0;j<2;j++)if(e->mod[s].osc[j].f[0]&&e->mod[s].osc[j].f[8]==dest)v+=mixed*e->mod_depth[s][j]+e->mod_offset[s][j];return v;}
static void mod_advance(Engine *e,int frames,double bpm){double dt=e->sample_rate>0&&frames>0?(double)frames/e->sample_rate:0;if(dt>1)dt=0;if(!isfinite(bpm)||bpm<=0||bpm>1000)bpm=e->mod_bpm;if(bpm!=e->mod_bpm){e->mod_trace_dirty=(1u<<MOD_SLOTS)-1;e->mod_bpm=bpm;for(int s=0;s<MOD_SLOTS;s++)mod_coefficients(e,s);}for(int s=0;s<MOD_SLOTS;s++)for(int j=0;j<2;j++){int run=mod_running(e,s,j),i=e->mod_pad[s];if(run!=e->mod_running_cache[s][j]&&i>=0)e->mod_armed[i][j]=0;e->mod_running_cache[s][j]=run;if(!run)continue;e->mod_phase[s][j]+=dt*e->mod_hz[s][j];if(e->mod_phase[s][j]>1e9)e->mod_phase[s][j]=fmod(e->mod_phase[s][j],1e9);}e->mod_seconds+=dt;}
static int mod_active(Engine *e,int i){int s=mod_slot_for(e,i);return s>=0&&((e->mod[s].osc[0].f[0]&&e->mod[s].osc[0].f[8])||(e->mod[s].osc[1].f[0]&&e->mod[s].osc[1].f[8]));}
static void mod_step_values(Engine *e,int i,double tick,int source,double dt,double bpm,int v[6]){(void)bpm;Lane *l=&e->lane[i];int base[6]={effective_value(l,source,1),effective_value(l,source,2),l->f[5],l->f[7],effective_value(l,source,3),effective_value(l,source,4)};int lo[]={1,0,0,10,1,0},hi[]={127,100,50,95,8,150};double scale[]={126,100,50,85,7,150};if(!mod_active(e,i)){memcpy(v,base,sizeof base);return;}if(e->mod_latch_valid[i]&&e->mod_latch_tick[i]==tick){memcpy(v,e->mod_latch[i],sizeof base);return;}int s=mod_slot_for(e,i);double mixed=mod_mixed_slot(e,s,dt);for(int k=0;k<6;k++)v[k]=clampi(base[k]+(int)lround(mod_amount_mixed(e,s,k+1,mixed)*scale[k]),lo[k],hi[k]);memcpy(e->mod_latch[i],v,sizeof base);e->mod_latch_tick[i]=tick;e->mod_latch_valid[i]=1;}
static int mod_pattern_blocked(Engine *e,int i){for(int k=0;k<LANES;k++)if(e->mod_owner[k]>=0&&e->active_note[k]==note(e,i)&&e->active_ch[k]==e->channel)return 1;return 0;}
/* Remove this lane's obsolete future offs without deleting events before handover. */
static int mod_cancel_from(Engine *e,int line,double at){if(!e->seq)return 1;snd_seq_remove_events_set_condition(e->rem,SND_SEQ_REMOVE_OUTPUT|SND_SEQ_REMOVE_TAG_MATCH|SND_SEQ_REMOVE_TIME_AFTER);snd_seq_remove_events_set_tag(e->rem,line+1);snd_seq_timestamp_t t;memset(&t,0,sizeof t);t.time.tv_sec=(unsigned)at;t.time.tv_nsec=(unsigned)((at-t.time.tv_sec)*1e9);snd_seq_remove_events_set_time(e->rem,&t);snd_seq_remove_events_set_queue(e->rem,e->queue);if(snd_seq_remove_events(e->seq,e->rem)<0){e->errors++;return 0;}return 1;}
static void mod_trigger(Engine *e,const Hit *h,double at){int i=h->line,j=h->repeat,n=note(e,i);if(h->kind==1){if(e->mod_owner[i]!=j)return;if(send_event(e,i,0,e->active_note[i],e->active_ch[i],0,at)){e->mod_owner[i]=-1;e->active_note[i]=-1;}else e->release_pending|=1u<<i;return;}if(!audible(e,i)||(e->release_pending&(1u<<i)))return;
 for(int k=0;k<LANES;k++)if(e->active_note[k]>=0&&(k==i||(e->active_note[k]==n&&e->active_ch[k]==e->channel))){if(!mod_cancel_from(e,k,at)||(e->active_off[k]>=at-1e-7&&!send_event(e,k,0,e->active_note[k],e->active_ch[k],0,at))){e->release_pending|=1u<<k;return;}e->active_note[k]=-1;e->mod_owner[k]=-1;}
 if(send_event(e,i,1,n,e->channel,h->velocity,at)){e->active_note[i]=n;e->active_ch[i]=e->channel;e->active_off[i]=INFINITY;e->mod_owner[i]=j;flash_enqueue(e,i,at);}else e->release_pending|=1u<<i;
}
/* Preserve 1 ms threshold sampling and hysteresis. Shared source evaluation
   removes duplicate wave calculations without changing the crossing algorithm. */
static int mod_events(Engine *e,Hit *hits,int *nh,double a,double b,double bpm,double time_base,int *budget){(void)time_base;double duration=(b-a)*60/bpm;int samples=(int)ceil(duration/.001);if(samples<1)samples=1;if(samples>2048){e->errors++;return 0;}
 for(int s=0;s<MOD_SLOTS;s++){int i=e->mod_pad[s];if(i<0)continue;int enabled[2];for(int j=0;j<2;j++){enabled[j]=mod_running(e,s,j)&&e->mod[s].osc[j].f[8]==MOD_DEST_NOTE;if(!enabled[j])e->mod_armed[i][j]=0;}if(!enabled[0]&&!enabled[1])continue;
 for(int k=0;k<samples;k++){double dt=duration*k/samples,mixed=mod_mixed_slot(e,s,dt+e->mod_span_offset);for(int j=0;j<2;j++){if(!enabled[j])continue;ModOsc *o=&e->mod[s].osc[j];double value=mixed*e->mod_depth[s][j]+e->mod_offset[s][j],threshold=o->f[9]/100.;int high=e->mod_high[i][j];if(!e->mod_armed[i][j]){e->mod_high[i][j]=value>=threshold;e->mod_armed[i][j]=1;continue;}if(value>threshold+.002)high=1;else if(value<threshold-.002)high=0;if(high==e->mod_high[i][j])continue;e->mod_high[i][j]=high;if(*nh>=EVENTS||*budget<=0){e->errors++;return 0;}int vel=clampi(e->lane[i].f[4]+(int)lround(mod_amount_mixed(e,s,1,mixed)*126),1,127);hits[(*nh)++]=(Hit){i,0,j,vel,a+dt*bpm/60.,0,high?2:1};(*budget)--;}}}
 return 1;}
/* Pictures are cached per slot and never depend on running phase, transport,
   ON/OFF, tempo or the visible tab. No animated output meters remain. */
/* Four 4/4 bars (16 quarter-note beats). Pair-encoded segments retain
   discontinuity connectors; very dense segments use a min/max envelope rather
   than display a falsely aliased slow wave. Only edit/tempo changes invalidate. */
static void mod_preview(Engine *e,int s){if(!(e->mod_trace_dirty&(1u<<s)))return;for(int j=0;j<2;j++){const ModOsc *o=&e->mod[s].osc[j];double cycles=e->mod_hz[s][j]*16*60/e->mod_bpm;
 for(int k=0;k<128;k++){double phase=(k/128.)*cycles+o->f[7]/360.,next=((k+1)/128.)*cycles+o->f[7]/360.;double a,b;if(cycles/128.>.25){a=1;b=-1;}else{a=mod_shape(o,phase,0x74391u);b=mod_shape(o,next,0x74391u);}/* resolved as a dense range, never a spurious low frequency */
 a=fmax(-1.,fmin(1.,a*e->mod_depth[s][j]+e->mod_offset[s][j]));b=fmax(-1.,fmin(1.,b*e->mod_depth[s][j]+e->mod_offset[s][j]));int qa=clampi((int)lround((a+1)*15.5),0,31),qb=clampi((int)lround((b+1)*15.5),0,31);e->mod_trace_cache[s][j][k]=qa*32+qb;}

 }e->mod_trace_dirty&=~(1u<<s);}
static int mod_style(Engine *e,int j){const ModOsc *o=&e->mod[e->mod_selected].osc[j];if(e->mod_hz[e->mod_selected][j]*16*60/e->mod_bpm/128.>.25)return 2;return o->f[1]==4||o->f[1]==5;}
static void mod_visual_key(int id,char *b,int n){if(id<LANES)snprintf(b,n,"mod_indicator%d",id);else if(id<LANES+4)snprintf(b,n,"mod_choose%d",id-LANES);else if(id==LANES+4)snprintf(b,n,"mod_pad");else if(id==LANES+5+30)snprintf(b,n,"mod_stairs0");else if(id==LANES+5+62)snprintf(b,n,"mod_stairs1");else if(id==LANES+5+31)snprintf(b,n,"mod_slot");else if(id==LANES+5+63)snprintf(b,n,"mod_tempo");else snprintf(b,n,"mod_trace%d_%d",(id-LANES-5)/32,(id-LANES-5)%32);}
static int mod_visual(Engine *e,int id){if(id<LANES)return mod_active(e,id);if(id<LANES+4)return 0;if(id==LANES+4)return e->mod_pad[e->mod_selected]+1;if(id==LANES+5+30||id==LANES+5+62){int j=id==LANES+5+30?0:1;return mod_style(e,j);}if(id==LANES+5+31)return e->mod_selected;if(id==LANES+5+63)return (int)lround(e->mod_bpm);int j=(id-LANES-5)/32,k=(id-LANES-5)%32;mod_preview(e,e->mod_selected);return e->mod_trace_cache[e->mod_selected][j][k];}
static int mod_get(Engine *e,const char *key,char *b,int size){int s,k;if(strncmp(key,"mod",3)&&key[0]!='l')return -1;if(!strcmp(key,"mod_tempo_display"))return snprintf(b,size,"4 BARS / %.1f BPM",e->mod_bpm);if(!strcmp(key,"mod_tempo"))return snprintf(b,size,"%d",(int)lround(e->mod_bpm));if(!strcmp(key,"mod_slot"))return snprintf(b,size,"%d",e->mod_selected);if(!strcmp(key,"mod_pad"))return snprintf(b,size,"%d",e->mod_pad[e->mod_selected]+1);if(parse_suffix(key,"mod_choose",MOD_SLOTS,&k))return snprintf(b,size,"0");if(mod_parse(e,key,&s,&k)){if(s<0)return snprintf(b,size,"0");return snprintf(b,size,"%d",k?e->mod[s].osc[(k-1)/MOD_FIELDS].f[(k-1)%MOD_FIELDS]:e->mod[s].mix);}int id=-1,j,end=0;if(parse_suffix(key,"mod_stairs",2,&k))return snprintf(b,size,"%d",mod_style(e,k));if(parse_suffix(key,"mod_indicator",LANES,&k))id=k;else if(sscanf(key,"mod_trace%d_%d%n",&j,&k,&end)==2&&key[end]==0&&j>=0&&j<2&&k>=0&&k<32)id=LANES+5+j*32+k;if(id>=0)return snprintf(b,size,"%d",mod_visual(e,id));if(!strncmp(key,"mod",3)&&key[3]>='0'&&key[3]<='1'&&!strcmp(key+4,"_hz_display"))return snprintf(b,size,"%.3f Hz",.05*pow(400.,e->mod[e->mod_selected].osc[key[3]-'0'].f[4]/1000.));return -1;}
